const config = $('Config').first().json;
const batchResponse = $('Fetch Data and Schema Sheets').first().json;
const sheets = batchResponse.sheets || [];

const extractValues = (rowData) => {
  if (!rowData) return [];
  return rowData.map(row =>
    (row.values || []).map(cell => {
      const uev = cell?.userEnteredValue;
      if (!uev) return '';
      return uev.stringValue ?? uev.numberValue ?? uev.boolValue ?? '';
    })
  );
};

const schemaSheet = sheets.find(s => s.properties?.title === config.schema_sheet_name);
const schemaValues = schemaSheet ? extractValues(schemaSheet.data?.[0]?.rowData) : [];
const dataSheet = sheets.find(s => s.properties?.title === config.data_sheet_name);
const dataValues = dataSheet ? extractValues(dataSheet.data?.[0]?.rowData) : [];

// Try to get schema from multiple sources
let schemaRows = [];

// Source 1: If schema was just created via LLM, use that output
try {
  const llmOutput = $('Generate Schema with LLM').first().json.output;
  if (Array.isArray(llmOutput) && llmOutput.length > 0) {
    schemaRows = llmOutput;
  }
} catch (e) {
  // LLM path not taken, try sheet data
}

// Source 2: If schema exists in sheet, parse from raw response
if (schemaRows.length === 0) {
  const schemaHeaders = schemaValues[0] || [];
  schemaRows = schemaValues.slice(1).map(row => {
    const obj = {};
    schemaHeaders.forEach((h, i) => obj[h] = row[i] || '');
    return obj;
  });
}

// Get data sheet info for filtering already-processed files
const dataHeaders = dataValues[0] || [];
const dataRows = dataValues.slice(1).map(row => {
  const obj = {};
  dataHeaders.forEach((h, i) => obj[h] = row[i] || '');
  return obj;
});

const driveFiles = $input.all();

// Build extraction object from schema
const internalFields = ['source_file', 'text_to_interpret', 'extraction_status', 'row_number'];
const userColumns = schemaRows.filter(row => {
  const name = (row.ColumnName || '').trim();
  return name && !internalFields.includes(name.toLowerCase());
});

// Validate: class columns must have Classes defined
for (const row of userColumns) {
  if (row.Type === 'class') {
    const vals = (row.Classes || '').split(',').map(s => s.trim()).filter(Boolean);
    if (vals.length === 0) {
      throw new Error(
        `Schema error in schema sheet (${config.schema_sheet_name}): column "${row.ColumnName}" has Type "class" but the "Classes" column is empty. ` +
        `Fix: add comma-separated values to the "Classes" column for "${row.ColumnName}".`
      );
    }
  }
}

let extraction = {};
if (userColumns.length > 0) {
  const focus_fields = userColumns.map(r => r.ColumnName);
  const field_schemas = userColumns.map(r => ({
    name: r.ColumnName,
    type: r.Type || 'str',
    description: r.Description || '',
    classes: r.Classes || ''
  }));

  const instructionLines = userColumns.map(r => {
    const name = r.ColumnName;
    const type = r.Type || 'str';
    const desc = r.Description || '';
    const classes = r.Classes || '';
    let line = `- ${name}`;
    if (type === 'class' && classes) line += ` (enum: ${classes})`;
    else if (type === 'list') line += ` (array)`;
    else if (type === 'date') line += ` (date)`;
    else if (type === 'int') line += ` (number)`;
    if (desc) line += `: ${desc}`;
    return line;
  });

  extraction = {
    type: 'document_analysis',
    focus_fields,
    field_schemas,
    instructions: `Extract ALL visible information from the document. Additionally, PRIORITIZE these fields (use these exact key names if the information is present):\n${instructionLines.join('\n')}\n\nInclude any other relevant information you observe (logos, text, context, etc.).`
  };
}

// Filter out already-processed files (resumability).
// A row whose extraction_status starts with "failed" does not count as done:
// that file is tried again, and Write Extracted Row updates its row in place.
const col = config.source_file_column;
const done = new Set();
for (const r of dataRows) {
  const val = (r[col] || '').trim().toLowerCase();
  if (!val) continue;
  if (!String(r.extraction_status || '').toLowerCase().startsWith('failed')) done.add(val);
}

let filtered = driveFiles.filter(f => {
  const name = (f.json.name || '').trim().toLowerCase();
  return name && !done.has(name);
});

// Include filter: if not "all", only keep files in the list
const includeRaw = (config.file_include || 'all').trim();
if (includeRaw.toLowerCase() !== 'all') {
  const includeSet = new Set(
    includeRaw.split(',').map(s => s.trim().toLowerCase()).filter(Boolean)
  );
  filtered = filtered.filter(f =>
    includeSet.has((f.json.name || '').trim().toLowerCase())
  );
}

// Exclude filter: remove files in the list
const excludeRaw = (config.file_exclude || '').trim();
if (excludeRaw) {
  const excludeSet = new Set(
    excludeRaw.split(',').map(s => s.trim().toLowerCase()).filter(Boolean)
  );
  filtered = filtered.filter(f =>
    !excludeSet.has((f.json.name || '').trim().toLowerCase())
  );
}

// Limit: cap the number of files to process
const fileLimit = config.file_limit;
if (fileLimit != null && fileLimit > 0) {
  filtered = filtered.slice(0, fileLimit);
}

// Size filter: skip files exceeding max_file_size_mb
const maxSizeMB = config.max_file_size_mb;
if (maxSizeMB != null && maxSizeMB > 0) {
  const maxBytes = maxSizeMB * 1024 * 1024;
  filtered = filtered.filter(f => {
    const sizeBytes = parseInt(f.json.size || '0', 10);
    return sizeBytes <= maxBytes;
  });
}

return filtered.map(f => ({ json: { ...f.json, _extraction: extraction } }));

const item = $input.first();
const config = $('Config').first().json;
const batchSize = config.batch_size || 10;
const extraction = $('Build Output Schema and Filter').first().json._extraction || {};
const fieldSchemas = extraction.field_schemas || [];

// No batching needed — pass through unchanged
if (fieldSchemas.length <= batchSize) {
  return [{ json: { ...item.json, _extraction: extraction }, binary: item.binary }];
}

// Split field_schemas into batches, rebuild extraction per batch
const batches = [];
for (let i = 0; i < fieldSchemas.length; i += batchSize) {
  const batchSchemas = fieldSchemas.slice(i, i + batchSize);
  const instructionLines = batchSchemas.map(r => {
    const name = r.name;
    const type = r.type || 'str';
    const desc = r.description || '';
    const classes = r.classes || '';
    let line = `- ${name}`;
    if (type === 'class' && classes) line += ` (enum: ${classes})`;
    else if (type === 'list') line += ` (array)`;
    else if (type === 'date') line += ` (date)`;
    else if (type === 'int') line += ` (number)`;
    if (desc) line += `: ${desc}`;
    return line;
  });
  batches.push({
    type: extraction.type || 'document_analysis',
    focus_fields: batchSchemas.map(s => s.name),
    field_schemas: batchSchemas,
    instructions: `Extract ALL visible information from the document. Additionally, PRIORITIZE these fields (use these exact key names if the information is present):\n${instructionLines.join('\n')}\n\nInclude any other relevant information you observe (logos, text, context, etc.).`
  });
}

return batches.map(batch => ({
  json: { ...item.json, _extraction: batch },
  binary: item.binary
}));

// One row per file, always. A file that fails still gets a row, so the loop
// keeps going and the failure is visible in the sheet. The next run retries it.
const idx = $('Loop Over Files').context['currentRunIndex'] ?? 0;
const listed = $('Build Output Schema and Filter').all()[idx]?.json || {};
let fileName = listed.name;
if (!fileName) {
  try { fileName = $('Download File').first().json.name; } catch (e) {}
}
fileName = fileName || 'unknown';

const outputs = $input.all();
const errorText = (e) => typeof e === 'string' ? e : (e?.message || JSON.stringify(e));
const stage = $prevNode.name === 'Download File' ? 'download' : 'conversion';

let failure = '';
const errored = outputs.find(o => o.json?.error && !o.json?.status);
const unsupported = outputs.find(o => o.json?.status === 'unsupported');
if (stage === 'download') {
  // Only the Download File error output leads here directly.
  failure = `failed: download - ${errored ? errorText(errored.json.error) : 'no error detail returned'}`;
} else if (errored) {
  // The converter failed on this file (or could not be called). n8n's own message follows.
  failure = `failed: converter - ${errorText(errored.json.error)}`;
} else if (unsupported) {
  // Not retried and does not fail the run: retrying cannot change the file type.
  failure = `skipped: unsupported file type (${unsupported.json.error?.mimeType || 'unknown type'})`;
}

// Merge all batch outputs into one object
const merged = {};
let lastRawText = '';
let parsedFields = false;
if (!failure) {
  for (const output of outputs) {
    const converterOutput = output.json;
    const rawText = converterOutput?.data?.text || converterOutput?.text || '';
    if (!rawText.trim()) continue;
    lastRawText = rawText;
    try {
      let parsed = JSON.parse(rawText);
      if (Array.isArray(parsed)) parsed = parsed[0] || {};
      if (typeof parsed === 'object' && parsed !== null) {
        Object.assign(merged, parsed);
        parsedFields = true;
      }
    } catch (e) {
      // not JSON: the text itself is kept in Text_to_interpret below
    }
  }
  if (!lastRawText.trim()) failure = 'failed: conversion - converter returned no text';
}

let rowData;
if (failure) {
  // Leave the user's columns empty rather than guess at them.
  rowData = { source_file: fileName, extraction_status: failure.slice(0, 500) };
} else {
  rowData = {
    ...merged,
    source_file: fileName,
    Text_to_interpret: lastRawText,
    extraction_status: parsedFields ? 'ok' : 'ok: text only, no fields parsed',
  };
  delete rowData.content_class;
  delete rowData.class_confidence;
  delete rowData.confidence;
}


return [{ json: rowData }];

// Runs once, after the last file. Failed files already have their row in the
// sheet; this makes the run itself say so. Without it the execution ends green,
// and an error workflow (FailedItems, resolver, alerts) never hears about it.
const rows = [];
for (let run = 0; ; run++) {
  let items;
  try { items = $('Prepare Write Data').all(0, run); } catch (e) { break; }
  if (!items.length) break;
  rows.push(...items.map(i => i.json));
}
const failed = rows.filter(r => String(r.extraction_status || '').startsWith('failed'));
const summary = { files: rows.length, ok: rows.length - failed.length, failed: failed.length };

if (failed.length && $('Config').first().json.fail_run_on_file_errors) {
  const list = failed.slice(0, 5).map(r => `${r.source_file}: ${r.extraction_status}`).join(' | ');
  const more = failed.length > 5 ? ` | and ${failed.length - 5} more` : '';
  throw new Error(`${failed.length} of ${rows.length} files failed. Rerun to retry only those. ${list}${more}`);
}
return [{ json: summary }];
